from scipy.optimize import minimize
import numpy as np

def objective(counts):
    counts = np.maximum(counts, 1)
    m = 0
    for i in range(len(counts) - 2):
        m += counts[i] * counts[i+1] * counts[i+2]
    n = 0
    for i in range(len(counts) - 3):
        n += counts[i] * counts[i+1] * counts[i+2] * counts[i+3]
    return -(m - n)

def solve_for_k(k, total_n):
    cons = ({'type': 'eq', 'fun': lambda x: np.sum(x) - total_n})
    bnds = [(1, total_n) for _ in range(k)]
    res = minimize(objective, [total_n/k]*k, bounds=bnds, constraints=cons)
    return -res.fun

for k in range(3, 10):
    print(f"k={k}, max_m_minus_n={solve_for_k(k, 2025)}")

def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            divs.append(n // i)
    return sorted(divs)

