def count_m(A):
    m = 0
    n_len = len(A)
    for i in range(n_len):
        for j in range(i + 1, n_len):
            if A[j] == A[i] + 1:
                for k in range(j + 1, n_len):
                    if A[k] == A[j] + 1:
                        m += 1
    return m

# Test sorted
